package dev.veltraph.client.chocolate;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
class ChocolateQueueManualReconciliationTest {
    static class Port extends ChocolateFactoryTest.Port {int hotbar;@Override public int currentHotbarSlot(){return hotbar;}}
    record Case(Port port,ChocolateFactoryRuntime runtime,ChocolateFactoryProfile profile,ChocolateFactoryModule.Journal pending){}
    static Case unknown(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);assertTrue(rt.select(ChocolateFactoryTest.profile(),ChocolateFactoryTest.observation(1,1,"200","old"),"employee",ChocolateFactoryTest.n("100"),BigDecimal.ZERO,1000));rt.tick(ChocolateFactoryTest.profile(),1000);rt.cancel();var j=new ChocolateFactoryModule.Journal(1,"local-test","2026-09-30","UNKNOWN","employee","100","0","unknown","0",rt.selection().intentId());return new Case(port,rt,ChocolateFactoryTest.profile(),j);}
    static ChocolateFactoryObservation observation(boolean purchased){return ChocolateFactoryTest.observation(2,purchased?2:1,purchased?"100":"200",purchased?"new":"old");}
    static ChocolateQueueManualReconciliation.Plan plan(Case c,boolean purchased){return ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,c.pending(),"local-test",purchased,observation(purchased),0,1500);}
    static ChocolateFactoryObservation changed(ChocolateFactoryObservation o,String scope,Object session,Object menu,Object screen,boolean complete,boolean bound,boolean cursor,long time,Map<Integer,ChocolateFactoryObservation.Row> rows){return new ChocolateFactoryObservation(scope,session,menu,screen,o.revision(),time,o.title(),complete,cursor,rows,o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),o.quotes(),o.targets(),bound);}
    @Test void manualPurchasedIsSeparateDebitNeverNativeACKOrFinancialReceipt(){var c=unknown();var p=plan(c,true);assertEquals(0,c.runtime().spent().signum());assertEquals(0,c.runtime().manualDeclaredDebit().signum());var history=new AtomicReference<>(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").with(c.pending())));var snapshot=c.runtime().manualClosureSnapshot();assertTrue(ChocolateManualReconciliationTransaction.commit(p.pending(),p.resolved(),j->{assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,c.runtime().state());history.set(ChocolateFactoryHistory.decode(history.get().withManualQueueJournal(j)));},()->true,()->c.runtime().matchesManualClosure(p),()->c.runtime().closeManualReconciliation(p),()->c.runtime().restoreOwnedManualClosure(snapshot)));assertEquals(ChocolateFactoryRuntime.State.IDLE,c.runtime().state());assertEquals(0,c.runtime().spent().signum());assertEquals(ChocolateFactoryTest.n("100"),c.runtime().manualDeclaredDebit());assertTrue(c.runtime().acknowledgedUpgrades().isEmpty());assertTrue(history.get().receipts().isEmpty());assertEquals("100",history.get().profiles().get("local-test").manualDeclaredDebit());assertEquals("employee",history.get().profiles().get("local-test").upgrade());assertEquals("100",history.get().profiles().get("local-test").price());assertFalse(history.get().pending());assertFalse(c.runtime().matchesManualClosure(p));assertEquals(1,c.port().clicks);}
    @Test void writeAndFlushFailureKeepOriginalIntentAccountingAndSameDeclarationRetry(){for(boolean writing:List.of(false,true)){var c=unknown();var p=plan(c,true);var memory=new AtomicReference<>(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").with(c.pending())));var disk=new AtomicReference<>(memory.get());var writes=new AtomicInteger();var snap=c.runtime().manualClosureSnapshot();assertFalse(ChocolateManualReconciliationTransaction.commit(p.pending(),p.resolved(),j->{if(writing&&writes.incrementAndGet()==1)throw new IllegalStateException("write failed");memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j)));},()->false,()->true,()->c.runtime().closeManualReconciliation(p),()->c.runtime().restoreOwnedManualClosure(snap)));assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,c.runtime().state());assertSame(p.selection(),c.runtime().selection());assertEquals(0,c.runtime().spent().signum());assertEquals(0,c.runtime().manualDeclaredDebit().signum());assertTrue(memory.get().pending());assertTrue(disk.get().pending());var retry=plan(c,true);assertTrue(ChocolateManualReconciliationTransaction.commit(retry.pending(),retry.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->{disk.set(memory.get());return true;},()->c.runtime().matchesManualClosure(retry),()->c.runtime().closeManualReconciliation(retry),()->c.runtime().restoreOwnedManualClosure(snap)));assertEquals(ChocolateFactoryTest.n("100"),c.runtime().manualDeclaredDebit());assertTrue(c.runtime().acknowledgedUpgrades().isEmpty());assertTrue(disk.get().receipts().isEmpty());assertFalse(c.runtime().matchesManualClosure(retry));}}
    @Test void closeCallbackThrowRestoresOriginalRuntimeAndPendingJournal(){var c=unknown();var p=plan(c,true);var memory=new AtomicReference<>(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").with(c.pending())));var snap=c.runtime().manualClosureSnapshot();assertFalse(ChocolateManualReconciliationTransaction.commit(p.pending(),p.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->true,()->true,()->{c.runtime().closeManualReconciliation(p);throw new IllegalStateException("after-close callback failure");},()->c.runtime().restoreOwnedManualClosure(snap)));assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,c.runtime().state());assertSame(p.selection(),c.runtime().selection());assertEquals(0,c.runtime().spent().signum());assertEquals(0,c.runtime().manualDeclaredDebit().signum());assertTrue(c.runtime().acknowledgedUpgrades().isEmpty());assertTrue(memory.get().pending());}
    @Test void durableFlushThenContextDriftDoesNotCloseOrManufactureAccounting(){var c=unknown();var p=plan(c,true);var memory=new AtomicReference<>(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").with(c.pending())));var snap=c.runtime().manualClosureSnapshot();assertFalse(ChocolateManualReconciliationTransaction.commit(p.pending(),p.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->{c.port().hotbar=1;return true;},()->c.port().hotbar==p.hotbar()&&c.runtime().matchesManualClosure(p),()->c.runtime().closeManualReconciliation(p),()->c.runtime().restoreOwnedManualClosure(snap)));assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,c.runtime().state());assertEquals(0,c.runtime().manualDeclaredDebit().signum());assertTrue(memory.get().pending());}
    @Test void anotherIntentDuringFlushIsNeverOverwrittenAndOriginalArchiveStaysPending(){var c=unknown();var p=plan(c,true);var memory=new AtomicReference<>(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").with(c.pending())));var snap=c.runtime().manualClosureSnapshot();var newId=new AtomicReference<String>();assertFalse(ChocolateManualReconciliationTransaction.commit(p.pending(),p.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->{c.runtime().closeManualReconciliation(p);assertTrue(c.runtime().selectQueue(c.profile(),observation(false),List.of("employee"),ChocolateFactoryTest.n("100"),BigDecimal.ZERO,1500));newId.set(c.runtime().selection().intentId());var next=new ChocolateFactoryModule.Journal(1,"local-test","2026-09-30","PENDING","employee","100","0","another intent","0",newId.get());memory.set(ChocolateFactoryHistory.decode(memory.get().with(next)));return true;},()->c.runtime().matchesManualClosure(p),()->c.runtime().closeManualReconciliation(p),()->c.runtime().restoreOwnedManualClosure(snap)));assertEquals(ChocolateFactoryRuntime.State.SELECTED,c.runtime().state());assertEquals(newId.get(),c.runtime().selection().intentId());assertEquals(newId.get(),memory.get().profiles().get("local-test").intentId());assertEquals("PENDING",memory.get().queueIntents().get(newId.get()).status());assertEquals("UNKNOWN",memory.get().queueIntents().get(c.pending().intentId()).status());assertTrue(memory.get().pending());assertThrows(IllegalStateException.class,()->c.runtime().restoreOwnedManualClosure(snap));}
    @Test void wrongScopeChangedProfileAndJournalCannotReachWrite(){var c=unknown();for(String scope:List.of("other",""))assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,c.pending(),scope,true,observation(true),0,1500));assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),false,c.pending(),"local-test",true,observation(true),0,1500));var wrong=new ChocolateFactoryModule.Journal(1,"other","2026-09-30","UNKNOWN","employee","100","0","wrong","0",c.pending().intentId());assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,wrong,"local-test",true,observation(true),0,1500));assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,c.runtime().state());assertEquals(0,c.runtime().manualDeclaredDebit().signum());}
    @Test void sessionMenuScreenHotbarStaleIncompleteCursorAndInventoryDriftAreDenied(){var c=unknown();var o=observation(true);var rows=new HashMap<>(o.rows());rows.remove(10);var bad=List.of(changed(o,o.scope(),new Object(),o.menu(),o.screen(),true,true,true,1000,o.rows()),changed(o,o.scope(),o.session(),new Object(),o.screen(),true,true,true,1000,o.rows()),changed(o,o.scope(),o.session(),o.menu(),new Object(),true,true,true,1000,o.rows()),changed(o,o.scope(),o.session(),o.menu(),o.screen(),false,true,true,1000,o.rows()),changed(o,o.scope(),o.session(),o.menu(),o.screen(),true,false,true,1000,o.rows()),changed(o,o.scope(),o.session(),o.menu(),o.screen(),true,true,false,1000,o.rows()),changed(o,o.scope(),o.session(),o.menu(),o.screen(),true,true,true,0,o.rows()),changed(o,o.scope(),o.session(),o.menu(),o.screen(),true,true,true,1000,rows));for(var inspect:bad)assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,c.pending(),"local-test",true,inspect,0,1500));assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,c.pending(),"local-test",true,o,1,1500));assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,c.runtime().state());}
    @Test void mismatchedDeclaredOutcomeTargetAndDebitCannotBeAdopted(){var c=unknown();assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,c.pending(),"local-test",true,observation(false),0,1500));assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,c.pending(),"local-test",false,observation(true),0,1500));var jump=ChocolateFactoryTest.observation(2,3,"100","jump");assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,c.pending(),"local-test",true,jump,0,1500));var unknownDebit=ChocolateFactoryTest.observation(2,2,"50","new");assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,c.pending(),"local-test",true,unknownDebit,0,1500));}
    @Test void restartJournalWithoutOriginalSelectionStaysPendingNotSilentlyCleared(){var c=unknown();var rebuilt=new ChocolateFactoryRuntime(new Port());assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(rebuilt,c.profile(),true,c.pending(),"local-test",true,observation(true),0,1500));assertTrue(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").with(c.pending())).pending());assertTrue(rebuilt.acknowledgedUpgrades().isEmpty());}
    @Test void manualDebitProtectsCurrentBudgetUntilSuccessfulFreshWalletSelection(){var c=unknown();var p=plan(c,true);c.runtime().closeManualReconciliation(p);assertEquals(ChocolateFactoryTest.n("100"),c.runtime().manualDeclaredDebit());assertFalse(c.runtime().select(c.profile(),observation(true),"employee",ChocolateFactoryTest.n("100"),BigDecimal.ZERO,1500));assertEquals(ChocolateFactoryTest.n("100"),c.runtime().manualDeclaredDebit());assertFalse(c.runtime().selectQueue(c.profile(),observation(true),List.of("employee"),ChocolateFactoryTest.n("100"),BigDecimal.ZERO,2501));assertEquals(ChocolateFactoryTest.n("100"),c.runtime().manualDeclaredDebit());assertTrue(c.runtime().selectQueue(c.profile(),observation(true),List.of("employee"),ChocolateFactoryTest.n("100"),BigDecimal.ZERO,1500));assertEquals(0,c.runtime().manualDeclaredDebit().signum());assertEquals(1,c.port().clicks);}
    @Test void oldSchemaJournalDecodesWithZeroManualAndNoRecoveryAuthority(){var j=new com.google.gson.Gson().fromJson("{\"schema\":1,\"scope\":\"local-test\",\"verifiedOn\":\"2026-09-30\",\"status\":\"UNKNOWN\",\"upgrade\":\"employee\",\"price\":\"100\",\"spent\":\"0\",\"reason\":\"unknown\"}",ChocolateFactoryModule.Journal.class);assertEquals("0",j.manualDeclaredDebit());assertEquals("",j.intentId());var c=unknown();assertThrows(IllegalArgumentException.class,()->ChocolateQueueManualReconciliation.prepare(c.runtime(),c.profile(),true,j,"local-test",true,observation(true),0,1500));}
    @Test void knownNativeACKAccountingAndUUIDSurviveFailedManualClose(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);assertTrue(rt.select(ChocolateFactoryTest.profile(),ChocolateFactoryTest.observation(1,1,"200","old"),"employee",ChocolateFactoryTest.n("100"),BigDecimal.ZERO,1000));rt.tick(ChocolateFactoryTest.profile(),1000);port.observation=observation(true);rt.tick(ChocolateFactoryTest.profile(),1500);assertEquals(ChocolateFactoryRuntime.State.ACKNOWLEDGED,rt.state());var ack=rt.acknowledgedUpgrades().getFirst();var pending=new ChocolateFactoryModule.Journal(1,"local-test","2026-09-30","ACKNOWLEDGED_UNPERSISTED","employee","100","100","failed native receipt persistence","0",rt.selection().intentId());var p=ChocolateQueueManualReconciliation.prepare(rt,ChocolateFactoryTest.profile(),true,pending,"local-test",true,observation(true),0,1500);var memory=new AtomicReference<>(ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").with(pending)));var snapshot=rt.manualClosureSnapshot();assertFalse(ChocolateManualReconciliationTransaction.commit(p.pending(),p.resolved(),j->memory.set(ChocolateFactoryHistory.decode(memory.get().withManualQueueJournal(j))),()->true,()->true,()->{rt.closeManualReconciliation(p);throw new IllegalStateException("close failure");},()->rt.restoreOwnedManualClosure(snapshot)));assertEquals(ChocolateFactoryRuntime.State.ACKNOWLEDGED,rt.state());assertEquals(ChocolateFactoryTest.n("100"),rt.spent());assertEquals(0,rt.manualDeclaredDebit().signum());assertEquals(List.of(ack),rt.acknowledgedUpgrades());assertEquals(pending,memory.get().profiles().get("local-test"));assertTrue(memory.get().pending());}

}
